+
+/* There is similar code in tvbuff.c ... */
+
+static gdouble
+spdu_ieee_double_from_64bits(guint64 value) {
+    union {
+        gdouble d;
+        guint64 w;
+    } ieee_fp_union;
+
+    ieee_fp_union.w = value;
+
+    return ieee_fp_union.d;
+}
+
+static gfloat
+spdu_ieee_float_from_32bits(guint32 value) {
+    union {
+        gfloat d;
+        guint32 w;
+    } ieee_fp_union;
+
+    ieee_fp_union.w = value;
+
+    return ieee_fp_union.d;
+}
